use anyhow::{ensure,Result};use serde::{Deserialize,Serialize};use serde_json::{Value,json};use std::io::Read;
#[derive(Clone,Default,Serialize,Deserialize)]
#[serde(rename_all="camelCase")]
pub struct Config{#[serde(default)]pub ai_base:String,#[serde(default)]pub ai_key:String,#[serde(default)]pub model:String,#[serde(default="search_default")]pub search_base:String,#[serde(default)]pub search_key:String,#[serde(default)]pub dav_url:String,#[serde(default)]pub dav_user:String,#[serde(default)]pub dav_password:String}
fn search_default()->String{"https://api.deepseek.com".into()}
pub fn https(url:&str)->Result<()> {let u=url::Url::parse(url)?;ensure!(u.scheme()=="https"&&u.host_str().is_some()&&u.username().is_empty()&&u.password().is_none()&&u.fragment().is_none(),"地址必须是HTTPS且不携带用户名、密码、片段");Ok(())}
pub fn request(method:&str,url:&str,auth:&str,body:Option<&[u8]>,headers:&[(&str,&str)],max:usize)->Result<(u16,Vec<u8>)>{
    https(url)?;let agent=ureq::AgentBuilder::new().timeout_connect(std::time::Duration::from_secs(20)).timeout_read(std::time::Duration::from_secs(120)).timeout(std::time::Duration::from_secs(180)).redirects(0).build();let mut req=agent.request(method,url).set("Accept","application/json");if !auth.is_empty(){req=req.set("Authorization",auth);}for(k,v)in headers{req=req.set(k,v);}
    let res=match if let Some(bytes)=body{req.send_bytes(bytes)}else{req.call()}{Ok(r)=>r,Err(ureq::Error::Status(_,r))=>r,Err(_)=>anyhow::bail!("连接或TLS失败，请检查网络与接口地址")};let status=res.status();let mut bytes=vec![];res.into_reader().take(max as u64+1).read_to_end(&mut bytes)?;ensure!(bytes.len()<=max,"响应超过大小限制");Ok((status,bytes))
}
pub fn post(url:&str,key:&str,body:&Value)->Result<Value>{ensure!(!key.trim().is_empty(),"请先配置API Key");let bytes=serde_json::to_vec(body)?;let(code,data)=request("POST",url,&format!("Bearer {key}"),Some(&bytes),&[("Content-Type","application/json")],8*1024*1024)?;ensure!((200..300).contains(&code),"{}",status_error(code));Ok(serde_json::from_slice(&data)?)}
pub fn status_error(code:u16)->String{format!("HTTP {code}：{}",match code{400=>"请求不兼容，请检查模型或参数",401=>"认证失败，请检查Key/账号密码",402=>"服务余额不足",403=>"权限不足或请求被拒绝",404=>"接口/文件不存在",429=>"请求频率超限，请稍后重试",_=>"服务请求未完成；不自动携带凭据跟随重定向"})}
pub fn search_request(query:&str,count:u32)->Result<Value>{let q=query.trim();ensure!((1..=128).contains(&q.chars().count()),"搜索词需要1–128个Unicode字符");ensure!((1..=50).contains(&count),"count应为1–50");Ok(json!({"query":q,"count":count,"need_content":true}))}
pub fn search_key(config:&Config)->Result<&str>{if !config.search_key.trim().is_empty(){return Ok(&config.search_key);}let host=url::Url::parse(&config.ai_base).ok().and_then(|u|u.host_str().map(String::from));ensure!(host.as_deref()==Some("api.deepseek.com"),"当前主模型不是DeepSeek官方接口，请在高级设置填写DeepSeek搜索Key");Ok(&config.ai_key)}
pub fn search(config:&Config,query:&str)->Result<Value>{let base=if config.search_base.is_empty(){"https://api.deepseek.com"}else{config.search_base.trim_end_matches('/')};let result=post(&format!("{base}/v1/tools/search"),search_key(config)?,&search_request(query,5)?)?;ensure!(result["results"].is_array(),"搜索响应缺少results");Ok(result["results"].clone())}
pub fn fetch(config:&Config,url:&str)->Result<Value>{let u=url::Url::parse(url)?;ensure!(["https","http"].contains(&u.scheme())&&u.host_str().is_some()&&u.username().is_empty()&&u.password().is_none()&&url.len()<=8192,"抓取地址无效");let base=if config.search_base.is_empty(){"https://api.deepseek.com"}else{config.search_base.trim_end_matches('/')};post(&format!("{base}/v1/tools/fetch"),search_key(config)?,&json!({"url":url}))}
#[cfg(test)]mod tests{use super::*;#[test]fn official_search_schema(){let r=search_request("学习方法",5).unwrap();assert_eq!(r["count"],5);assert_eq!(r["need_content"],true);assert!(r.get("max_results").is_none());assert!(search_request(&"😀".repeat(128),5).is_ok());assert!(search_request(&"题".repeat(129),5).is_err());assert!(search_request("",5).is_err());}#[test]fn no_cleartext_credentials(){assert!(https("https://api.deepseek.com").is_ok());assert!(https("http://example.com").is_err());assert!(https("https://u:p@example.com").is_err());}}
